pub fn mnDiagram_DrawCellValue<'a>(ctx: &'a Ctx, arg0: HSD_GObj<'a>, col: u8, row: u8, arg3: i32) {
    let __frame = ctx.stack_frame(0xa8);
    let mut arg0 = arg0;
    let mut col = col;
    let mut row = row;
    let mut arg3 = arg3;
    let mut data_alias: Diagram<'a> = null(ctx);
    let mut row_offset_adj: f64 = 0.0;
    let mut jobj: HSD_JObj<'a> = null(ctx);
    let mut jobj2: HSD_JObj<'a> = null(ctx);
    let mut data: Diagram<'a> = null(ctx);
    let mut model: StaticModelDesc<'a> = null(ctx);
    let mut digit_count: i32 = 0;
    let mut digit: i32 = 0;
    let mut i: i32 = 0;
    let mut x_spacing: f64 = 0.0;
    let mut y_spacing: f64 = 0.0;
    let mut base: f64 = 0.0;
    let mut rowf: f64 = 0.0;
    let mut row_offset: f64 = 0.0;
    let mut col_offset: f64 = 0.0;
    let mut y_offset: f64 = 0.0;
    data = Handle::cast::<Diagram<'a>>((arg0).user_data());
    data_alias = data;
    jobj = (data).jobjs().at(11_i32).get();
    base = inl_HSD_JObjGetTranslationX(ctx, jobj);
    jobj2 = (data).jobjs().at(12_i32).get();
    x_spacing = fp::fsubs(inl_HSD_JObjGetTranslationX(ctx, jobj2), base);
    jobj = (data).jobjs().at(7_i32).get();
    base = inl_HSD_JObjGetTranslationX(ctx, jobj);
    jobj2 = (data).jobjs().at(8_i32).get();
    y_spacing = fp::fsubs(inl_HSD_JObjGetTranslationX(ctx, jobj2), base);
    jobj = (data).jobjs().at(9_i32).get();
    base = inl_HSD_JObjGetTranslationY(ctx, jobj);
    jobj2 = (data).jobjs().at(10_i32).get();
    y_offset = fp::fsubs(inl_HSD_JObjGetTranslationY(ctx, jobj2), base);
    digit_count = fns::mn_GetDigitCount(ctx, arg3);
    col_offset = fp::fmuls(y_spacing, fp::frsp(col as f64));
    rowf = fp::frsp(row as f64);
    row_offset = fp::fmuls(y_offset, rowf);
    row_offset_adj = fp::fsubs(row_offset, 0.4000000059604645);
    model = fns::MenMainNmB_Top(ctx);
    {
        i = 0_i32;
        'l1: while i < digit_count {
            'c2: {
                digit = fns::mn_GetDigitAt(ctx, arg3, i);
                jobj = fns::HSD_JObjLoadJoint(ctx, (model).joint());
                fns::HSD_JObjAddAnimAll(
                    ctx,
                    jobj,
                    (model).animjoint(),
                    (model).matanim_joint(),
                    (model).shapeanim_joint(),
                );
                inl_requestIntegerAnimFrame(ctx, jobj, digit);
                fns::HSD_JObjAnimAll(ctx, jobj);
                if (col as i32) < 7_i32 {
                    inl_HSD_JObjSetTranslateX(
                        ctx,
                        jobj,
                        fp::fmadds(x_spacing, fp::frsp(i as f64), col_offset),
                    );
                } else {
                    inl_HSD_JObjSetTranslateX(
                        ctx,
                        jobj,
                        fp::fadds(
                            fp::fmadds(x_spacing, fp::frsp(i as f64), col_offset),
                            0.4000000059604645,
                        ),
                    );
                }
                if (row as i32) < 10_i32 {
                    inl_HSD_JObjSetTranslateY(ctx, jobj, row_offset);
                } else {
                    inl_HSD_JObjSetTranslateY(ctx, jobj, row_offset_adj);
                }
                fns::HSD_JObjAddChild(ctx, (data_alias).jobjs().at(11_i32).get(), jobj);
            }
            i = i.wrapping_add(1);
        }
    }
}

